CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, name TEXT NOT NULL, phone TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, referral_code TEXT NOT NULL UNIQUE, referred_by_user_id TEXT REFERENCES users(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, status TEXT NOT NULL DEFAULT 'active');
CREATE TABLE IF NOT EXISTS sessions (token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), expires_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS ledger (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), type TEXT NOT NULL, direction TEXT NOT NULL CHECK(direction IN ('credit','debit')), amount_ugx INTEGER NOT NULL CHECK(amount_ugx > 0), status TEXT NOT NULL CHECK(status IN ('pending','successful','failed','reversed')), reference TEXT UNIQUE, description TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS products (id INTEGER PRIMARY KEY, name TEXT NOT NULL, price_ugx INTEGER NOT NULL, daily_income_ugx INTEGER NOT NULL, duration_days INTEGER NOT NULL, active INTEGER NOT NULL DEFAULT 1);
INSERT OR IGNORE INTO products VALUES (1,'Machine 1',15000,5000,60,1),(2,'Machine 2',30000,10000,45,1),(3,'Machine 3',60000,20000,30,1),(4,'Machine 4',120000,30000,15,1),(5,'Machine 5',250000,62500,15,1),(6,'Machine 6',500000,125000,15,1),(7,'Machine 7',1000000,250000,10,1),(8,'Machine 8',1500000,500000,10,1),(9,'Machine 9',2000000,750000,10,1),(10,'Machine 10',1000000,250000,30,1);
CREATE TABLE IF NOT EXISTS user_products (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), product_id INTEGER NOT NULL REFERENCES products(id), purchase_ledger_id TEXT NOT NULL UNIQUE REFERENCES ledger(id), purchased_at TEXT NOT NULL, starts_at TEXT NOT NULL, ends_at TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'active');
CREATE TABLE IF NOT EXISTS payment_events (provider TEXT NOT NULL, provider_event_id TEXT NOT NULL, event_type TEXT NOT NULL, status TEXT NOT NULL, received_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(provider,provider_event_id));
CREATE TABLE IF NOT EXISTS referral_commissions (id TEXT PRIMARY KEY, source_user_id TEXT NOT NULL REFERENCES users(id), beneficiary_user_id TEXT NOT NULL REFERENCES users(id), level INTEGER NOT NULL CHECK(level BETWEEN 1 AND 3), base_deposit_ledger_id TEXT NOT NULL REFERENCES ledger(id), amount_ugx INTEGER NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(beneficiary_user_id,base_deposit_ledger_id,level));